import{_ as s,o as n,c as e,ai as i}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"代码质量规范","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality/code-quality.md","filePath":"ai/productivity/dev-spec/03-quality/code-quality.md"}'),l={name:"ai/productivity/dev-spec/03-quality/code-quality.md"};function t(r,a,p,d,c,o){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="代码质量规范" tabindex="-1">代码质量规范 <a class="header-anchor" href="#代码质量规范" aria-label="Permalink to “代码质量规范”">​</a></h1><blockquote><p>第三层 · 质量保障。这一层贯穿项目准备到最终交付的每一步，不是收工才执行。本页聚焦「怎么让代码本身可靠」——审查有清单、改动有边界、问题有依据。</p></blockquote><h2 id="贯穿全流程的定位" tabindex="-1">贯穿全流程的定位 <a class="header-anchor" href="#贯穿全流程的定位" aria-label="Permalink to “贯穿全流程的定位”">​</a></h2><p>第三层不是第二层之后的「第九步」。它在每个阶段都生效：</p><table tabindex="0"><thead><tr><th>阶段</th><th>代码质量在做什么</th></tr></thead><tbody><tr><td>项目准备</td><td>确认代码规范、禁改区、构建检查命令</td></tr><tr><td>需求 / 架构</td><td>把质量要求写进验收标准和方案</td></tr><tr><td>开发</td><td>每轮改动做局部质量检查</td></tr><tr><td>审查</td><td>按清单逐项核对</td></tr><tr><td>修复 / 重构 / 测试</td><td>保证修复不引入新问题、重构不改行为</td></tr><tr><td>交付</td><td>diff 全量检查、遗留问题归零</td></tr></tbody></table><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="代码审查清单" tabindex="-1">代码审查清单 <a class="header-anchor" href="#代码审查清单" aria-label="Permalink to “代码审查清单”">​</a></h3><ul><li><strong>逻辑与规则</strong>：业务规则实现完整，边界条件（空值、零值、重复、越权）处理到位。</li><li><strong>异常与事务</strong>：异常不被吞掉，事务边界合理，失败不留半状态数据。</li><li><strong>兼容性</strong>：接口签名、字段含义、返回结构变化已确认，调用方不受影响。</li><li><strong>测试</strong>：关键路径和失败路径有测试，断言没被放宽或删除。</li><li><strong>改动范围</strong>：没有无关格式化、未用 import、调试打印、注释掉的分支、遗留 TODO。</li><li><strong>可读性</strong>：命名和分层符合项目现有风格，没有明显重复或更简单的写法。</li></ul><h3 id="硬红线" tabindex="-1">硬红线 <a class="header-anchor" href="#硬红线" aria-label="Permalink to “硬红线”">​</a></h3><p>发现以下情况必须处理，不能带过：</p><ul><li>硬编码特定值绕过问题。</li><li>吞掉异常让错误消失。</li><li>放宽断言、删除失败用例让测试变绿。</li><li>给某条数据加特判掩盖规则问题。</li><li>改动超出约定范围、触碰禁改区。</li></ul><h3 id="让-ai-有效自查" tabindex="-1">让 AI 有效自查 <a class="header-anchor" href="#让-ai-有效自查" aria-label="Permalink to “让 AI 有效自查”">​</a></h3><ul><li>明确要求「只输出问题清单和依据，不修改文件、不宣布通过」。</li><li>每条问题指到 <code>文件:行号</code> 和依据，不说「整体还行」。</li><li>审查者不判定通过，最终由人判定（见 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/agents.html">Agents</a>）。</li><li>能脚本化的检查（构建、lint、密钥扫描、禁改区 diff）交给脚本（见 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/hooks-scripts.html">Hooks / Scripts</a>），不靠提示词提醒。</li></ul><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>代码质量自查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请对下面的改动做代码质量自查，只输出问题清单，不修改文件，不宣布通过。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改动：&lt;粘贴 diff 或代码&gt;</span></span>
<span class="line"><span>约定：修改范围、禁改区、项目规范（粘贴）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按清单检查：</span></span>
<span class="line"><span>1. 逻辑与业务规则完整性、边界条件。</span></span>
<span class="line"><span>2. 异常处理与事务边界。</span></span>
<span class="line"><span>3. 接口、字段、数据兼容性。</span></span>
<span class="line"><span>4. 测试覆盖与断言是否被放宽。</span></span>
<span class="line"><span>5. 改动范围：无关格式化、未用 import、调试打印、注释分支、遗留 TODO。</span></span>
<span class="line"><span>6. 可读性与重复代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每条问题给「文件:行号 | 问题 | 依据 | 建议改法」。</span></span>
<span class="line"><span>单独列出硬红线命中项（硬编码、吞异常、放宽断言、数据特判、越界改动）。</span></span>
<span class="line"><span>没有问题也逐项写「已检查，无问题」，不要只给结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 审查清单逐项过完，问题带文件行号和依据。</li><li>[ ] 硬红线命中项为零，或已全部处理。</li><li>[ ] 改动范围合规，没有遗留调试代码。</li><li>[ ] AI 自查没有自行宣布通过，判定由人做。</li></ul><p>质量检查的细节手法见 <a href="/my-vitepress-site/ai/prompts/coding.html">提示词库 · 编程开发</a>。</p>`,18)])])}const u=s(l,[["render",t]]);export{b as __pageData,u as default};
